import socket
import time
import sys

HOST = 'crypto.chal.csaw.io'
PORT = 5000
TIMEOUT = 5

def recv_with_timeout(sock, timeout=TIMEOUT):
    sock.settimeout(timeout)
    try:
        data = sock.recv(4096)
        return data
    except socket.timeout:
        return b''

def main():
    s = socket.create_connection((HOST, PORT), timeout=5)
    banner = recv_with_timeout(s)
    if banner:
        sys.stdout.buffer.write(b'[BANNER]\n'+banner+b'\n')
    else:
        print('[NO_BANNER]')
    s.sendall(b'{"curve": "curve_s256"}\n')
    resp = recv_with_timeout(s)
    if resp:
        sys.stdout.buffer.write(b'[RESP1]\n'+resp+b'\n')
    else:
        print('[NO_RESP1]')
    s.sendall(b'{"Gx": "79be667ef9dcbbac55a06295ce870b07029bfcdb2dce28d959f2815b16f81798", "Gy": "483ada7726a3c4655da4fbfc0e1108a8fd17b448a68554199c47d08ffb10d4b8"}\n')
    resp2 = recv_with_timeout(s)
    if resp2:
        sys.stdout.buffer.write(b'[RESP2]\n'+resp2+b'\n')
    else:
        print('[NO_RESP2]')
    s.close()

    # Now try again with curve_p256
    try:
        s2 = socket.create_connection((HOST, PORT), timeout=5)
        banner2 = recv_with_timeout(s2)
        if banner2:
            sys.stdout.buffer.write(b'[BANNER2]\n'+banner2+b'\n')
        else:
            print('[NO_BANNER2]')
        s2.sendall(b'{"curve": "curve_p256"}\n')
        resp3 = recv_with_timeout(s2)
        if resp3:
            sys.stdout.buffer.write(b'[RESP3]\n'+resp3+b'\n')
        else:
            print('[NO_RESP3]')
        # Standard generator for P-256
        gx = "6b17d1f2e12c4247f8bce6e563a440f277037d812deb33a0f4a13945d898c296"
        gy = "4fe342e2fe1a7f9b8ee7eb4a7c0f9e162bce33576b315ececbb6406837bf51f5"
        payload = '{{"Gx": "{}", "Gy": "{}"}}\n'.format(gx, gy).encode()
        s2.sendall(payload)
        resp4 = recv_with_timeout(s2)
        if resp4:
            sys.stdout.buffer.write(b'[RESP4]\n'+resp4+b'\n')
        else:
            print('[NO_RESP4]')
        s2.close()
    except Exception as e:
        print(f'[EXC2] {e}')

if __name__ == "__main__":
    main()

